component.css:
.metro{--acc:#2d5680;--acc2:#4e86b4;--ink:#2a3440;--panel:#f8f0de;position:relative;width:100%;aspect-ratio:1672/941;container-type:size;overflow:hidden;border-radius:10px;background:#0d1420;font-family:"PingFang SC","Microsoft YaHei",sans-serif;user-select:none;-webkit-user-select:none}
.metro *,.metro *::before,.metro *::after{ box-sizing:border-box}
.metro button{ font-family:inherit;border:0;background:none;padding:0;margin:0;cursor:pointer;color:inherit}
.metro button:focus{ outline:none}
.metro button:focus-visible{ outline:2px solid var(--acc2);outline-offset:1px}
.mt-stage{ position:absolute;inset:0;opacity:0;transition:opacity .7s}
.metro[data-boot="ready"] .mt-stage{ opacity:1}
.mt-bg{position:absolute;inset:0;background-size:100% 100%;background-position:center;opacity:0;transition:opacity .45s;pointer-events:none}
.mt-bg--title{ background-image:url("https://origin.picgo.net/2026/10/02/100008507401de75923547b78f.png")}
.mt-bg--load{ background-image:url("https://origin.picgo.net/2026/10/11/100008601956a9163bf72203e4.png")}
.mt-bg--gallery{ background-image:url("https://origin.picgo.net/2026/10/11/1000086003dcd985929cc65c78.png")}
.mt-bg--settings{ background-image:url("https://origin.picgo.net/2026/10/13/10000859938a8d9260bec93cd4.png")}
.metro[data-page="title"] .mt-bg--title,
.metro[data-page="load"] .mt-bg--load,
.metro[data-page="gallery"] .mt-bg--gallery,
.metro[data-page="settings"] .mt-bg--settings{ opacity:1}
.mt-page{ position:absolute;inset:0;display:none;pointer-events:none}
.mt-page > *{ pointer-events:auto}
.metro[data-page="load"] .mt-page[data-pg="load"],
.metro[data-page="gallery"] .mt-page[data-pg="gallery"],
.metro[data-page="settings"] .mt-page[data-pg="settings"]{ display:block}
.mt-menu{ position:absolute;inset:0}
.metro:not([data-page="title"]) .mt-menu{display:none}
.mt-menu__item{position:absolute;left:2.5%;width:18%;height:7.5%;border-radius:4px}
.mt-menu__item::before{content:"";position:absolute;left:0;top:12%;bottom:12%;width:.5cqw;border-radius:2px;background:var(--acc2);opacity:0;transform:scaleY(.35);transform-origin:center;transition:opacity .18s,transform .18s}
.mt-menu__item::after{content:"";position:absolute;inset:4% 6%;border-radius:4px;background:#2d568000;box-shadow:inset 0 0 0 2px #4e86b400;transition:background .18s,box-shadow .18s}
@media (hover:hover){.mt-menu__item:hover::before{ opacity:1;transform:scaleY(1)}
.mt-menu__item:hover::after{ background:#2d56803d;box-shadow:inset 0 0 0 2px #4e86b480}}
.mt-slot{position:absolute;width:22.7%;height:23.2%;border-radius:6px;transition:transform .12s}
@media (hover:hover){.mt-slot:hover{ background:#2d568029;box-shadow:inset 0 0 0 2px #4e86b48c}}
.mt-slot:active{ transform:scale(.985)}
.mt-slot.is-flash{ animation:mtFlash .4s ease}
@keyframes mtFlash{0%{ background:#2d568000}
35%{ background:#2d56804d}
100%{ background:#2d568000}}
.mt-pager{position:absolute;inset:0;pointer-events:none}
.mt-pager__btn,.mt-pager__num{pointer-events:auto}
.mt-pager__btn,.mt-pager__num{position:absolute;top:83.5%;width:2.6%;height:5%;font-size:2.4cqh;line-height:1;color:var(--ink);display:flex;align-items:center;justify-content:center;border-radius:5px;transition:color .15s,background .15s}
.mt-pager__btn[data-to="prev"]{ left:42.55%}
.mt-pager__num[data-to="1"]{ left:45.6%}
.mt-pager__num[data-to="2"]{ left:49.65%}
.mt-pager__num[data-to="3"]{ left:54.2%}
.mt-pager__btn[data-to="next"]{ left:58.15%}
.mt-pager__btn{ font-weight:700}
.mt-pager__num.is-cur{ color:var(--acc);font-weight:700;text-decoration:underline}
@media (hover:hover){.mt-pager__btn:hover,.mt-pager__num:hover{ background:#2d568024}}
.mt-dd{ position:absolute;left:41.1%;top:32.95%;width:17.8%;height:3.9%;border-radius:6px}
.mt-dd[data-dd="mode"]{ left:80.5%;top:70.55%;width:15.5%;height:4.15%}
@media (hover:hover){.mt-dd:hover{ background:#2d568024;box-shadow:inset 0 0 0 2px #4e86b480}}
.mt-dd-label{ position:absolute;display:flex;align-items:center;padding-left:.9cqw;background:#f8f0def2;color:var(--ink);font-size:2.5cqh;border-radius:4px;opacity:0;pointer-events:none}
.mt-dd-label.is-show{ opacity:1}
[data-ddl="lang"]{ left:41.3%;top:32.95%;width:17.4%;height:3.9%}
[data-ddl="mode"]{ left:80.8%;top:70.65%;width:14.9%;height:3.5%;font-size:2.3cqh}
.mt-dd-pop{ position:absolute;z-index:4;display:flex;flex-direction:column;overflow:hidden;background:#f8f0de;border:1px solid #2a344038;border-radius:8px;box-shadow:0 6px 18px #141e2d40;opacity:0;transform:translateY(-6px);pointer-events:none;transition:opacity .18s,transform .18s}
.mt-dd-pop.is-open{ opacity:1;transform:none;pointer-events:auto}
.mt-dd-pop button{ padding:1.1cqh 1cqw;font-size:2.5cqh;color:var(--ink);text-align:left;white-space:nowrap}
.mt-dd-pop button.is-sel{ color:var(--acc);font-weight:700}
@media (hover:hover){.mt-dd-pop button:hover{ background:#2d56801f}}
[data-pop="lang"]{ left:41.1%;top:37.1%;width:17.8%}
[data-pop="mode"]{ left:80.5%;top:74.9%;width:15.5%}
.mt-slider{ position:absolute;width:15.3%;height:4.2%;cursor:pointer;touch-action:none}
.mt-slider::before{ content:"";position:absolute;left:0;right:0;top:50%;height:.8cqh;transform:translateY(-50%);background:#c5c2b9;border-radius:2px;box-shadow:inset 0 0 0 1px #2a34402e}
.mt-slider::after{ content:"";position:absolute;top:50%;left:calc(-3% + var(--p,0%) * .97);width:1.3cqw;height:2.3cqh;transform:translate(-50%,-50%);background:#f4eddf;border:2px solid #2a3440b3;border-radius:50%;box-shadow:0 1px 4px #141e2d40}
.mt-slider.is-drag::after{ box-shadow:0 0 0 5px #4e86b440,0 1px 4px #141e2d40}
.mt-slider[data-slider="b"]{ left:80.3%;top:32.65%}
.mt-slider[data-slider="s"]{ left:80.3%;top:38.75%}
.mt-slider[data-slider="v"]{ left:80.3%;top:45.05%}
.mt-slider[data-slider="ts"]{ left:43.6%;top:51.2%}
.mt-slider[data-slider="ad"]{ left:43.6%;top:58.05%}
.mt-tgrow{ position:absolute;width:4.6%;height:4.2%}
.mt-tgrow::before{ content:"";position:absolute;inset:15% 13%;border-radius:999px;background:#8e969e;box-shadow:inset 0 0 0 1.5px #2a344059;transition:background .2s}
.mt-tgrow::after{ content:"";position:absolute;top:50%;left:15%;width:27%;height:30%;border-radius:50%;background:#f4eddf;box-shadow:0 1px 3px #141e2d4d;transform:translateY(-50%);transition:left .2s}
.mt-tgrow.is-on::before{ background:var(--acc2)}
.mt-tgrow.is-on::after{ left:58%}
.mt-tgrow[data-tg="u"]{ left:54.7%;top:64.7%}
.mt-tgrow[data-tg="sk"]{ left:54.7%;top:71.3%}
.mt-tgrow[data-tg="f"]{ left:91.65%;top:63.95%}
#mtBack{ position:absolute;left:1.5%;top:94%;width:11.5%;height:4%;border-radius:6px;display:none}
.metro:not([data-page="title"]) #mtBack{ display:block}
@media (hover:hover){#mtBack:hover{ background:#2d56803d;box-shadow:inset 0 0 0 2px #4e86b480}}
#mtFs{ position:absolute;right:1%;top:94%;width:3.2%;height:4.5%;border-radius:6px;opacity:0;transition:opacity .25s}
#mtFs::before{ content:"";position:absolute;inset:16% 24%;border:2px solid #f8f0decc;border-radius:3px}
#mtFs::after{ content:"";position:absolute;left:24%;right:24%;top:48%;height:2px;background:#f8f0decc}
.metro:hover #mtFs,#mtFs:focus-visible{ opacity:.85}
@media (hover:none){#mtFs{ opacity:.5}}
.mt-true{position:fixed;left:-9999px;top:0;width:2px;height:2px;opacity:0;pointer-events:none}
.mt-intro{ position:absolute;inset:0;z-index:6;background:#000;transition:opacity .7s}
.mt-intro video{ position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
.metro[data-boot="ready"] .mt-intro{ opacity:0;pointer-events:none}
#mtSound{ position:absolute;left:50%;bottom:9%;transform:translateX(-50%);padding:1.6cqh 2.6cqw;font-size:2.8cqh;color:#fff;background:#141e2db3;border:1px solid #f8f0de59;border-radius:999px;opacity:0;pointer-events:none;transition:opacity .3s}
#mtSound.is-show{ opacity:1;pointer-events:auto}
.mt-modal{ position:absolute;inset:0;z-index:7;display:flex;align-items:center;justify-content:center;background:#0d142080;opacity:0;pointer-events:none;transition:opacity .2s}
.mt-modal.is-open{ opacity:1;pointer-events:auto}
.mt-modal__box{ width:34%;background:var(--panel);border-radius:12px;padding:3cqh 2.4cqw;box-shadow:0 12px 40px #0d142066;transform:translateY(8px) scale(.97);transition:transform .2s}
.mt-modal.is-open .mt-modal__box{ transform:none}
.mt-modal__txt{ margin:0 0 2.4cqh;font-size:3cqh;font-weight:700;color:var(--ink);text-align:center}
.mt-modal__txt span{ display:block;margin-top:.8cqh;font-size:2.2cqh;font-weight:400;color:#2a3440b3}
.mt-modal__row{ display:flex;gap:1.4cqw}
.mt-modal__btn{ flex:1;padding:1.8cqh 0;font-size:2.6cqh;border-radius:8px;background:#2d56801f;color:var(--ink);transition:filter .15s}
.mt-modal__btn--warn{ background:var(--acc);color:#fff}
@media (hover:hover){.mt-modal__btn:hover{ filter:brightness(1.1)}}#mtVer{position:absolute;right:1.1%;bottom:1.3%;font-size:2cqh;color:#c9d4e2;opacity:.5;z-index:2;transition:opacity .2s}
@media (hover:hover){#mtVer:hover{opacity:.9}}

component.script:
"use strict";(() => {
var D = String.fromCharCode(36);
var SL = String.fromCharCode(47);
var Z = n => "<" + D + n + D + ">";
var ZE = n => "<" + SL + D + n + D + ">";
var root = document.getElementById("mtRoot");
if (!root) return;
var q = s => root.querySelector(s);
var qa = s => Array.from(root.querySelectorAll(s));
var PAGES = { "标题": "title", "读取": "load", "画廊": "gallery", "设置": "settings" };
var LANGS = ["简体中文", "English", "日本語"];
var MODES = ["窗口模式", "全屏模式", "无边框窗口"];
var st = { pg: 1, ts: 0, ad: 0, b: 0, s: 0, v: 0, u: false, sk: false, f: false, lg: 0, md: 0 };
var stateStr = () =>
"p" + st.pg + ".ts" + st.ts + ".ad" + st.ad + ".b" + st.b + ".s" + st.s + ".v" + st.v +
".u" + (st.u ? 1 : 0) + ".sk" + (st.sk ? 1 : 0) + ".f" + (st.f ? 1 : 0) +
".l" + st.lg + ".m" + st.md;
var applyTok = t => {
if (!t) return;
var key = null;
if (t.indexOf("ts") === 0) key = "ts";
else if (t.indexOf("ad") === 0) key = "ad";
else if (t.indexOf("sk") === 0) key = "sk";
else key = t.charAt(0);
var num = parseInt(t.slice(key.length), 10);
if (isNaN(num)) return;
if (key === "p") st.pg = Math.min(3, Math.max(1, num));
else if (key === "u") st.u = num === 1;
else if (key === "sk") st.sk = num === 1;
else if (key === "f") st.f = num === 1;
else if (key === "l") st.lg = num;
else if (key === "m") st.md = num;
else if (key === "ts") st.ts = num;
else if (key === "ad") st.ad = num;
else if (key === "b") st.b = num;
else if (key === "s") st.s = num;
else if (key === "v") st.v = num;
};
var state = root.getAttribute("data-state") || "";
if (state) state.split(".").forEach(applyTok);
var page = PAGES[root.getAttribute("data-page") || ""] || "title";
root.dataset.page = page;
function closePops() { qa(".mt-dd-pop").forEach(el => el.classList.remove("is-open")); }
var gotoPage = p => { root.dataset.page = p; closePops(); };
var bootReady = () => { root.dataset.boot = "ready"; };

var video = q("#mtVideo"), soundBtn = q("#mtSound"), intro = q("#mtIntro");
var pv = window.__mtVideos || [];
for (var k = 0; k < pv.length; k++) { try { pv[k].pause(); pv[k].muted = true; } catch (e) {} }
if (root.getAttribute("data-boot") === "完成") {
try { video.pause(); video.muted = true; } catch (e) {}
bootReady();
} else {
var done = false;
var finish = () => { if (!done) { done = true; bootReady(); } };
var unmutePlay = () => {
video.muted = false;
var pr = video.play();
if (pr && pr.then) pr.then(() => soundBtn.classList.remove("is-show")).catch(() => {
video.muted = true;
video.play().catch(() => {});
soundBtn.classList.add("is-show");
});
};
video.addEventListener("ended", finish);
video.addEventListener("error", finish);
setTimeout(() => { if (video.readyState < 2) finish(); }, 16000);
video.muted = false;
var pr0 = video.play();
var showSound = () => soundBtn.classList.add("is-show");
if (pr0 && pr0.catch) pr0.catch(() => {
video.muted = true;
var pr1 = video.play();
if (pr1 && pr1.then) pr1.then(showSound).catch(showSound);
});
intro.addEventListener("click", unmutePlay);
soundBtn.addEventListener("click", e => { e.stopPropagation(); unmutePlay(); });
}

q("#mtMenu").addEventListener("click", e => {
var btn = e.target.closest("[data-act]");
if (!btn) return;
var act = btn.dataset.act;
if (act === "newgame") {
fillInput("开始游戏");
toast("已装填 —— 发送以开始旅程");
} else if (act === "exit") {
q("#mtModal").classList.add("is-open");
} else if (act === "load") {
if (typeof changeMsg === "function") changeMsg("" + Z("大都会读档") + ZE("大都会读档"));
else gotoPage("load");
} else if (act === "gallery") {
if (typeof changeMsg === "function") changeMsg("" + Z("大都会CG画廊") + "<解锁>" + "<" + SL + "解锁>" + ZE("大都会CG画廊"));
else gotoPage("gallery");
} else if (act === "settings") {
gotoPage("settings");
}
});
q("#mtBack").addEventListener("click", () => gotoPage("title"));

var modal = q("#mtModal");
modal.addEventListener("click", e => {
var btn = e.target.closest("[data-mb]");
if (btn) {
modal.classList.remove("is-open");
if (btn.dataset.mb === "quit") gotoPage("title");
return;
}
if (e.target === modal) modal.classList.remove("is-open");
});

qa(".mt-slot").forEach((el, i) => {
el.addEventListener("click", () => { toast("存档 " + (i + 1) + " · NO DATA"); });
});

var nums = qa(".mt-pager__num");
var syncNums = () => nums.forEach(el => el.classList.toggle("is-cur", parseInt(el.dataset.to || "1", 10) === st.pg));
var flashSlots = () => qa(".mt-slot").forEach(el => { el.classList.remove("is-flash"); void el.offsetWidth; el.classList.add("is-flash"); });
q("#mtPager").addEventListener("click", e => {
var btn = e.target.closest("[data-to]");
if (!btn) return;
var to = btn.dataset.to;
if (to === "prev") st.pg = st.pg <= 1 ? 3 : st.pg - 1;
else if (to === "next") st.pg = st.pg >= 3 ? 1 : st.pg + 1;
else if (to) st.pg = parseInt(to, 10);
syncNums();
flashSlots();
});
syncNums();

var SLIDER_KEYS = { ts: "ts", ad: "ad", b: "b", s: "s", v: "v" };
var dragging = null;
qa(".mt-slider").forEach(el => {
var key = SLIDER_KEYS[el.dataset.slider || ""];
if (!key) return;
el.style.setProperty("--p", st[key] + "%");
var setFrom = clientX => {
var rect = el.getBoundingClientRect();
var w = rect.width || 1;
var ratio = (clientX - rect.left) * (w ** -1);
var pct = Math.round(Math.max(0, Math.min(100, ratio * 100)));
el.style.setProperty("--p", pct + "%");
st[key] = pct;
};
el.addEventListener("pointerdown", e => {
dragging = el;
el.classList.add("is-drag");
try { el.setPointerCapture(e.pointerId); } catch (err) {}
setFrom(e.clientX);
});
el.addEventListener("pointermove", e => { if (dragging === el) setFrom(e.clientX); });
var drop = () => { dragging = null; el.classList.remove("is-drag"); };
el.addEventListener("pointerup", drop);
el.addEventListener("pointercancel", drop);
});
var TG_KEYS = { u: "u", sk: "sk", f: "f" };
qa(".mt-tgrow").forEach(el => {
var key = TG_KEYS[el.dataset.tg || ""];
if (!key) return;
el.classList.toggle("is-on", st[key]);
el.addEventListener("click", () => { st[key] = !st[key]; el.classList.toggle("is-on", st[key]); });
});

var DD = { lang: { list: LANGS, key: "lg" }, mode: { list: MODES, key: "md" } };
["lang", "mode"].forEach(name => {
var cfg = DD[name];
var btn = q('[data-dd="' + name + '"]');
var pop = q('[data-pop="' + name + '"]');
var label = q('[data-ddl="' + name + '"]');
var sync = () => {
var cur = st[cfg.key];
Array.from(pop.children).forEach((opt, i) => { opt.classList.toggle("is-sel", i === cur); });
if (cur > 0) { label.textContent = cfg.list[cur]; label.classList.add("is-show"); }
else label.classList.remove("is-show");
};
btn.addEventListener("click", e => {
e.stopPropagation();
var open = pop.classList.contains("is-open");
closePops();
if (!open) { sync(); pop.classList.add("is-open"); }
});
pop.addEventListener("click", e => {
var opt = e.target.closest("[data-val]");
if (opt) {
e.stopPropagation();
st[cfg.key] = parseInt(opt.dataset.val || "0", 10);
sync();
closePops();
}
});
sync();
});
q("#mtStage").addEventListener("click", e => {
if (!e.target.closest(".mt-dd-pop") && !e.target.closest(".mt-dd")) closePops();
});

q("#mtFs").addEventListener("click", () => {
if (root.requestFullscreen) root.requestFullscreen().catch(() => toast("当前环境不支持全屏"));
else toast("当前环境不支持全屏");
});

var vc = 0, vLock = false;
var tv = q("#mtTrue");
window.__mtVideos = [video, tv];
var trueGo = () => {
try { if (typeof changeMsg === "function") changeMsg("" + Z("大都会真结局走廊") + ZE("大都会真结局走廊")); } catch (e) {}
};
q("#mtVer").addEventListener("click", e => {
e.stopPropagation();
if (vLock) return;
if (++vc < 10) return;
vLock = true;
root.dataset.boot = "开场";
try { tv.currentTime = 0; } catch (_) {}
tv.muted = false;
var pr = tv.play();
if (pr && pr.catch) pr.catch(() => { tv.muted = true; var p2 = tv.play(); if (p2 && p2.catch) p2.catch(() => {}); });
tv.addEventListener("ended", trueGo);
tv.addEventListener("error", trueGo);
setTimeout(() => { if (tv.readyState < 2) trueGo(); }, 20000);
});
})();
